import{_ as e,o as d,c as o,a3 as r}from"./chunks/framework.BTQ4eCVb.js";const u=JSON.parse('{"title":"Invoices 1.1.0 — Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Invoices 1.1.0 — Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/invoices-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Invoices 1.1.0 — Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/invoices-production-readiness"}]]},"headers":[],"relativePath":"deployment/invoices-production-readiness.md","filePath":"deployment/invoices-production-readiness.md","lastUpdated":1787534699000}'),n={name:"deployment/invoices-production-readiness.md"};function i(a,t,s,c,l,g){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="invoices-1-1-0-—-production-readiness-audit" tabindex="-1">Invoices 1.1.0 — Production Readiness Audit <a class="header-anchor" href="#invoices-1-1-0-—-production-readiness-audit" aria-label="Permalink to &quot;Invoices 1.1.0 — Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-08-15</td></tr><tr><td><strong>Status</strong></td><td><strong>Go</strong> — staging → production after CI, migrate, and scheduler confirm</td></tr><tr><td><strong>Scope</strong></td><td>Tenant Invoices module <code>invoices</code> <strong>1.0.0 → 1.1.0</strong> (recurring series + PDF)</td></tr><tr><td><strong>Branch</strong></td><td><code>feature/recurring-invoices-pdf</code></td></tr><tr><td><strong>Companion</strong></td><td><a href="./invoices">Invoices production</a> · <a href="/developer-guide/invoices">Developer</a> · <a href="/user-guide/invoices">User</a> · <a href="/api/tenant-v1-invoices">API</a></td></tr></tbody></table><p>This is an additive MINOR on the existing customer-invoice module (not Stripe/Cashier, not Central <code>Invoice</code>). No new permissions or queues. Optional <code>INVOICES_*</code> env vars have production-safe defaults.</p><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>Workspaces that already entitled Invoices pick up recurring + PDF after migrate. Catalog bump does <strong>not</strong> auto-install for workspaces that never entitled the module.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td><code>module:invoices</code> + <code>invoices.*</code> (no new family)</td><td><strong>Pass</strong></td></tr><tr><td>PDF <code>invoices.view</code> + assignee scope + <code>throttle:invoices-pdf</code></td><td><strong>Pass</strong></td></tr><tr><td>Stop series <code>invoices.update</code>; optional void <code>invoices.void</code></td><td><strong>Pass</strong></td></tr><tr><td>Workspace timezone due generation</td><td><strong>Pass</strong></td></tr><tr><td>Idempotent daily generate + unique <code>(tenant, source, issue_date)</code></td><td><strong>Pass</strong></td></tr><tr><td>Soft-deleted occurrence does not unique-fail the tenant run</td><td><strong>Pass</strong> (F1)</td></tr><tr><td>Generator <code>chunkById</code> + per-tenant time budget</td><td><strong>Pass</strong> (F2)</td></tr><tr><td>PDF cache + warm job on send (default queue)</td><td><strong>Pass</strong> (F3)</td></tr><tr><td>Catch-up cap 52 + remaining periods next tick</td><td><strong>Pass</strong> (F4)</td></tr><tr><td>Command <strong>FAILURE</strong> if any tenant series fails</td><td><strong>Pass</strong> (F5)</td></tr><tr><td>Invoice memo on Overview + PDF</td><td><strong>Pass</strong> (F6)</td></tr><tr><td>Headed e2e stop with <code>void_latest_unpaid</code></td><td><strong>Pass</strong> (F7)</td></tr><tr><td>Dompdf <code>isRemoteEnabled=false</code>, Blade escaped</td><td><strong>Pass</strong></td></tr><tr><td>Catalog <code>1.1.0</code> migrate-only</td><td><strong>Pass</strong></td></tr><tr><td>Pest recurrence</td><td><strong>Pass</strong></td></tr><tr><td>Playwright headed one-session</td><td><strong>Pass</strong> (5)</td></tr><tr><td>Docs + upgrade + runbook</td><td><strong>Pass</strong></td></tr></tbody></table><p><strong>Go / No-Go:</strong> <strong>Go</strong> after companion CI, <code>composer install</code>, <code>php artisan migrate --force</code>, and confirming <code>invoices:generate-recurring</code> is on the production scheduler.</p><hr><h2 id="findings" tabindex="-1">Findings <a class="header-anchor" href="#findings" aria-label="Permalink to &quot;Findings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Status</th><th>Finding</th><th>Action</th></tr></thead><tbody><tr><td>F1</td><td>Medium</td><td><strong>Fixed</strong></td><td><code>alreadyIssued</code> ignored soft-deleted children, so retrying the same <code>issue_date</code> could hit the unique index and abort that tenant’s remaining series</td><td><code>withTrashed()</code> + per-series <code>try/catch</code>; Pest</td></tr><tr><td>F2</td><td>Medium</td><td><strong>Fixed</strong></td><td>Generator <code>get()</code>s all due series roots</td><td><code>chunkById</code> (<code>INVOICES_RECURRING_CHUNK_SIZE</code>, default 100) + per-tenant time budget</td></tr><tr><td>F3</td><td>Medium</td><td><strong>Fixed</strong></td><td>PDF is synchronous Dompdf on the request</td><td>Cache by id + <code>updated_at</code>; <code>WarmCustomerInvoicePdfJob</code> on send (default queue); <code>throttle:invoices-pdf</code></td></tr><tr><td>F4</td><td>Low</td><td><strong>Fixed</strong></td><td>Catch-up cap was 12 periods per run</td><td>Default <strong>52</strong>; remaining due periods run on the next daily tick; Pest cap=1 then two artisan runs</td></tr><tr><td>F5</td><td>Low</td><td><strong>Fixed</strong></td><td>Command logged <code>tenant_failed</code> and still exited 0</td><td>Returns <code>FAILURE</code> if any entitled tenant had a failed series or exception</td></tr><tr><td>F6</td><td>Low</td><td><strong>Fixed</strong></td><td>Invoice memo (<code>notes</code>) was on the PDF only</td><td>Overview shows the memo; Notes tab remains the activity stream</td></tr><tr><td>F7</td><td>Low</td><td><strong>Fixed</strong></td><td>Headed e2e stopped a series without <code>void_latest_unpaid</code></td><td>Generate a child from Playwright (tenant-scoped tinker), then check the void checkbox</td></tr></tbody></table><h3 id="accepted-intentional" tabindex="-1">Accepted / intentional <a class="header-anchor" href="#accepted-intentional" aria-label="Permalink to &quot;Accepted / intentional&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Notes</th></tr></thead><tbody><tr><td>No new permissions</td><td>Reuse <code>invoices.view</code> (PDF), <code>invoices.update</code> (stop), <code>invoices.void</code> (optional child void)</td></tr><tr><td>Generated invoices are <strong>Draft</strong></td><td>Operator sends; recurring generator does not auto-email</td></tr><tr><td>Stopping does not void paid history</td><td>Optional checkbox only voids latest unpaid generated draft/sent</td></tr><tr><td>No stored <code>pdf_path</code></td><td>Rendered on the fly (cached)</td></tr><tr><td>No new queue name</td><td>Warm job uses the <strong>default</strong> Redis queue</td></tr><tr><td>Customer email delivery</td><td><strong>Shipped</strong> in <strong>1.8.0</strong> — <code>POST …/email</code> (<code>invoices.send</code>, <code>throttle:billing-document-email</code>); see <a href="/api/tenant-v1-invoices">API</a> and <a href="/user-guide/invoices#email-customer">User guide</a></td></tr></tbody></table><hr><h2 id="test-evidence" tabindex="-1">Test evidence <a class="header-anchor" href="#test-evidence" aria-label="Permalink to &quot;Test evidence&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Suite</th><th>Result</th><th>Notes</th></tr></thead><tbody><tr><td><code>php artisan test --compact tests/Feature/Tenant/CustomerInvoice/CustomerInvoiceRecurrenceTest.php</code></td><td><strong>13 passed</strong></td><td>Activate on send, frequency required, generate + idempotent, timezone, stop, stop+void, reject stop on child, PDF + cache hit, PDF 403, catch-up cap, soft-delete skip, schedule registration, command failure exit</td></tr><tr><td><code>npm run test:e2e:invoices:headed</code></td><td><strong>5 passed (~7.5m with headed slowMo)</strong></td><td>One login session</td></tr></tbody></table><p><strong>Headed e2e (single session):</strong> empty/title-only validation; all five frequencies; create with tax totals; lines/Overview memo/timeline; edit; PDF from sheet and row menu; send; Sent KPI; void; recurring generate + stop with optional void; <code>n</code> / <code>Ctrl+F</code>; delete/restore; My invoices filter.</p><hr><h2 id="deploy-order" tabindex="-1">Deploy order <a class="header-anchor" href="#deploy-order" aria-label="Permalink to &quot;Deploy order&quot;">​</a></h2><ol><li><strong>Backend</strong> — <code>composer install</code> (pulls <code>dompdf/dompdf</code>) then <code>php artisan migrate --force</code> (recurrence columns + catalog <code>1.1.0</code>)</li><li>Confirm scheduler: <code>invoices:generate-recurring</code> daily, <code>withoutOverlapping(120)</code>, <code>onOneServer</code></li><li>Optional env only if you need to tune catch-up / PDF (see <a href="./invoices#optional-env">Invoices production</a>)</li><li><strong>SPA</strong> — recurring form, stop dialog, Download PDF, Overview memo</li><li><strong>Docs</strong></li><li>Staging smoke below before production traffic</li></ol><p>Suggested merge: <strong>Backend → Frontend → Docs</strong>. Do <strong>not</strong> <code>db:seed</code>.</p><hr><h2 id="pre-flight-checklist" tabindex="-1">Pre-flight checklist <a class="header-anchor" href="#pre-flight-checklist" aria-label="Permalink to &quot;Pre-flight checklist&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Check</th><th>Owner</th><th>Pass?</th></tr></thead><tbody><tr><td>1</td><td><code>composer install</code> includes <code>dompdf/dompdf</code></td><td>Ops</td><td>☐</td></tr><tr><td>2</td><td>Migrations applied (<code>add_recurrence_to_customer_invoices</code> + bump <code>1.1.0</code>)</td><td>Ops</td><td>☐</td></tr><tr><td>3</td><td>Catalog <code>invoices</code> version <code>1.1.0</code></td><td>Ops</td><td>☐</td></tr><tr><td>4</td><td>Scheduler has <code>invoices:generate-recurring</code></td><td>Ops</td><td>☐</td></tr><tr><td>5</td><td>Pest recurrence + existing <code>CustomerInvoiceTest</code> green in CI</td><td>Eng</td><td>☐</td></tr><tr><td>6</td><td>Playwright <code>test:e2e:invoices</code> green</td><td>QA</td><td>☐</td></tr><tr><td>7</td><td>Staging smoke signed off</td><td>QA / Ops</td><td>☐</td></tr></tbody></table><hr><h2 id="staging-smoke-human" tabindex="-1">Staging smoke (human) <a class="header-anchor" href="#staging-smoke-human" aria-label="Permalink to &quot;Staging smoke (human)&quot;">​</a></h2><ol><li>Marketplace → Invoices already installed (or install free)</li><li>New invoice → empty submit shows Title + Description required</li><li>Recurring on → frequencies Weekly / Monthly / Quarterly / Semi-annually / Yearly</li><li>Create draft with a line and a memo → Overview shows the memo → <strong>Download PDF</strong> (opens a <code>.pdf</code>)</li><li>Send recurring invoice → badge Recurring, <strong>Next invoice</strong>, <strong>Stop recurring</strong></li><li><code>php artisan invoices:generate-recurring</code> → a <strong>Draft</strong> child appears for the next period</li><li>Stop recurring and check <strong>Also void the latest unpaid generated invoice</strong></li><li>Void a sent non-recurring invoice</li><li>Soft-delete → Deleted only → Restore</li></ol><hr><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Action</th></tr></thead><tbody><tr><td>Frontend</td><td>Redeploy previous SPA (recurring/PDF UI disappears; API columns remain)</td></tr><tr><td>Backend code</td><td>Redeploy previous release; keep additive migrations</td></tr><tr><td>Module disable</td><td>Marketplace uninstall (invoice rows retained)</td></tr><tr><td>Schema</td><td>Do <strong>not</strong> roll back recurrence columns in prod without a data plan</td></tr><tr><td>Scheduler</td><td>Removing the command stops new drafts; existing series rows stay</td></tr></tbody></table><hr><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li>Domain timeline: <code>recurrence_started</code>, <code>recurrence_stopped</code>, <code>recurrence_generated</code></li><li>Logs: <code>invoices.generate-recurring.tenant_failed</code>, <code>invoices.generate-recurring.series_failed</code>, <code>invoices.generate-recurring.time_budget_reached</code>, <code>invoices.pdf.rendered</code>, <code>invoices.pdf.warm_failed</code></li><li>Nightwatch: <code>invoices:generate-recurring</code> duration and <strong>non-zero exit</strong>; <code>GET invoices/{id}/pdf</code> latency</li><li>Spatie log name <code>customer_invoices</code></li></ul><hr><h2 id="sign-off" tabindex="-1">Sign-off <a class="header-anchor" href="#sign-off" aria-label="Permalink to &quot;Sign-off&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Name</th><th>Date</th><th>Decision</th></tr></thead><tbody><tr><td>Engineering</td><td></td><td></td><td><strong>Go</strong> / No-Go</td></tr><tr><td>Product</td><td></td><td></td><td>F1–F7 fixed</td></tr><tr><td>Ops</td><td></td><td></td><td>Staging migrate + scheduler + smoke ☐</td></tr></tbody></table><p><strong>Recommendation:</strong> Merge companions after CI green; run staging smoke.</p>',37)])])}const p=e(n,[["render",i]]);export{u as __pageData,p as default};
